import{_ as t,o,c as r,a2 as n}from"./chunks/framework.e4u2V5E7.js";const m=JSON.parse('{"title":"React","description":"React reference documentation","frontmatter":{"title":"React","description":"React reference documentation"},"headers":[],"relativePath":"knowledge/react.md","filePath":"knowledge/react.md","lastUpdated":1784485118000}'),s={name:"knowledge/react.md"};function a(i,e,c,d,l,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="react" tabindex="-1">React <a class="header-anchor" href="#react" aria-label="Permalink to &quot;React&quot;">​</a></h1><h1 id="react-19-patterns-—-knowledge-reference" tabindex="-1">React 19 Patterns — Knowledge Reference <a class="header-anchor" href="#react-19-patterns-—-knowledge-reference" aria-label="Permalink to &quot;React 19 Patterns — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Reference for modern React 19 development covering hooks, component patterns, composition strategies, render optimization, concurrent features, and Server Components. Focused on production-quality patterns that scale.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="react-19-evolution" tabindex="-1">React 19 Evolution <a class="header-anchor" href="#react-19-evolution" aria-label="Permalink to &quot;React 19 Evolution&quot;">​</a></h3><p>React 19 introduces significant improvements: Server Components (stable), Actions for form handling, <code>use()</code> hook for reading promises/context in render, improved ref forwarding, document metadata, and stylesheet support. The concurrent rendering engine enables priority-based rendering and Suspense for data fetching.</p><h3 id="hooks-ecosystem" tabindex="-1">Hooks Ecosystem <a class="header-anchor" href="#hooks-ecosystem" aria-label="Permalink to &quot;Hooks Ecosystem&quot;">​</a></h3><ul><li><strong><code>useState</code></strong> — local state with lazy initialization; returns <code>[value, setter]</code></li><li><strong><code>useEffect</code></strong> — side effects with cleanup; runs after render, dependency array controls re-execution</li><li><strong><code>useCallback</code></strong> — memoizes function references; prevents unnecessary re-renders of child components</li><li><strong><code>useMemo</code></strong> — memoizes computed values; avoids expensive recalculations</li><li><strong><code>useRef</code></strong> — mutable container that persists across renders without triggering re-renders</li><li><strong><code>useContext</code></strong> — subscribes to context values; re-renders when context changes</li><li><strong><code>use()</code> (React 19)</strong> — reads promises or context during render; enables async component patterns</li><li><strong><code>useActionState</code></strong> (React 19) — manages form action state with pending/error/success states</li><li><strong><code>useFormStatus</code></strong> (React 19) — reads parent form submission status from child components</li><li><strong><code>useOptimistic</code></strong> (React 19) — provides optimistic state updates during async transitions</li><li><strong><code>useTransition</code></strong> — marks state updates as non-urgent transitions; keeps UI responsive</li></ul><h3 id="component-patterns" tabindex="-1">Component Patterns <a class="header-anchor" href="#component-patterns" aria-label="Permalink to &quot;Component Patterns&quot;">​</a></h3><ul><li><strong>Functional Components</strong> — the standard; always prefer over class components</li><li><strong>Compound Components</strong> — share implicit state via Context between related components</li><li><strong>Render Props</strong> — pass render functions for flexible composition (largely replaced by hooks)</li><li><strong>HOCs</strong> — wrap components for cross-cutting concerns (largely replaced by hooks)</li><li><strong>Container/Presentational</strong> — separate data fetching from display logic</li><li><strong>Controlled/Uncontrolled</strong> — form input patterns; controlled via state, uncontrolled via refs</li></ul><h3 id="composition-over-inheritance" tabindex="-1">Composition over Inheritance <a class="header-anchor" href="#composition-over-inheritance" aria-label="Permalink to &quot;Composition over Inheritance&quot;">​</a></h3><p>React favors composition. Use <code>children</code> prop, render props, and Context to share behavior rather than creating deep inheritance hierarchies. Wrapping components with HOCs or hooks is preferred over extending component classes.</p><h3 id="server-components" tabindex="-1">Server Components <a class="header-anchor" href="#server-components" aria-label="Permalink to &quot;Server Components&quot;">​</a></h3><p>Components that run only on the server. They can directly access databases, file systems, and backend services. They produce zero client-side JavaScript. They cannot use hooks, event handlers, or browser APIs.</p><h3 id="concurrent-features" tabindex="-1">Concurrent Features <a class="header-anchor" href="#concurrent-features" aria-label="Permalink to &quot;Concurrent Features&quot;">​</a></h3><p>React 18+ introduced concurrent rendering. <code>startTransition</code> marks updates as low priority. <code>Suspense</code> boundaries allow progressive loading. <code>useDeferredValue</code> defers expensive re-renders. These features enable responsive UIs during heavy computation.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Extract custom hooks for reusable logic</strong> — when you see <code>useEffect</code> + <code>useState</code> patterns repeated, encapsulate them into a named custom hook with clear semantics</li><li><strong>Use <code>useCallback</code> and <code>useMemo</code> strategically</strong> — only memoize values passed to memoized children or used as dependency array items; over-memoization adds overhead</li><li><strong>Lift state to the lowest common ancestor</strong> — only lift state as high as needed; avoid &quot;state drilling&quot; by using Context or composition</li><li><strong>Use <code>useTransition</code> for non-urgent updates</strong> — filtering, tab switching, and navigation should be transitions to keep input responsive</li><li><strong>Prefer controlled components for forms</strong> — controlled forms are predictable and testable; use uncontrolled only for performance-critical inputs</li><li><strong>Keep components small and focused</strong> — if a component handles multiple concerns, split it into focused subcomponents with clear responsibilities</li><li><strong>Use <code>key</code> correctly for lists</strong> — use stable, unique identifiers, never array indices for dynamic lists</li><li><strong>Handle loading and error states explicitly</strong> — every async-driven component should have loading, error, and empty states</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Overusing <code>useEffect</code> for derived state</strong> — if state can be computed from props or other state during render, use <code>useMemo</code> or compute directly; <code>useEffect</code> for derivation causes extra renders</li><li><strong>Mutating state directly</strong> — always use the setter from <code>useState</code>; direct mutations do not trigger re-renders</li><li><strong>Creating new objects/arrays in render without memoization</strong> — passing new references as props causes child re-renders; use <code>useMemo</code> for expensive objects</li><li><strong>Using <code>useEffect</code> with missing or incorrect dependencies</strong> — stale closures and infinite loops; use exhaustive-deps lint rule</li><li><strong>Passing inline functions to memoized children</strong> — destroys the benefit of <code>React.memo</code>; use <code>useCallback</code> for handler props</li><li><strong>Using context for frequently changing values</strong> — every consumer re-renders; split into granular contexts or use state management for high-frequency updates</li><li><strong>Not cleaning up subscriptions in <code>useEffect</code></strong> — return cleanup functions for timers, event listeners, and subscriptions to prevent memory leaks</li><li><strong>Using <code>index</code> as <code>key</code> for dynamic lists</strong> — causes reconciliation bugs when items are reordered, inserted, or removed</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Forgetting that <code>useState</code> triggers re-render</strong> — setting the same value still triggers a render (React 18+ skips it for primitives, but not for objects)</li><li><strong>Calling hooks conditionally</strong> — hooks must be called in the same order every render; never inside loops, conditions, or nested functions</li><li><strong>Not using <code>useRef</code> for DOM access</strong> — <code>document.querySelector</code> bypasses React&#39;s rendering; always use refs</li><li><strong>Treating <code>useEffect</code> cleanup as optional</strong> — missing cleanup causes memory leaks and stale state</li><li><strong>Over-memoizing simple values</strong> — <code>useMemo(() =&gt; a + b, [a, b])</code> adds overhead worse than recalculating; only memoize expensive computations</li><li><strong>Creating context for single-consumer values</strong> — prop drilling for 1-2 levels is simpler than context setup</li><li><strong>Ignoring React DevTools Profiler</strong> — performance issues are invisible without measuring; use the profiler before optimizing</li><li><strong>Not handling asynchronous errors</strong> — <code>Error Boundaries</code> do not catch async errors; use <code>Suspense</code> with fallback or handle in effects</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>Component needs local state</td><td><code>useState</code></td></tr><tr><td>Expensive computation from state</td><td><code>useMemo</code></td></tr><tr><td>Expensive function passed as prop</td><td><code>useCallback</code></td></tr><tr><td>DOM element access</td><td><code>useRef</code></td></tr><tr><td>Shared state across tree</td><td><code>useContext</code> or state management</td></tr><tr><td>Async data fetching</td><td>Server Component or <code>use()</code> in React 19</td></tr><tr><td>Form with server mutation</td><td><code>useActionState</code></td></tr><tr><td>Non-urgent state update</td><td><code>useTransition</code> + <code>useDeferredValue</code></td></tr><tr><td>Optimistic UI</td><td><code>useOptimistic</code></td></tr><tr><td>Complex reusable logic</td><td>Custom hook</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://react.dev" target="_blank" rel="noreferrer">React 19 Documentation</a></li><li><a href="https://react.dev/reference/react/hooks" target="_blank" rel="noreferrer">React Hooks Reference</a></li><li><a href="https://react.dev/reference/rsc/server-components" target="_blank" rel="noreferrer">React Server Components</a></li><li><a href="https://react.dev/learn" target="_blank" rel="noreferrer">React Performance Guide</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li>React 19&#39;s <code>use()</code> hook is experimental in some environments; check framework support before adopting</li><li><code>React.memo</code> is rarely needed with proper hook usage; prefer component composition to avoid re-renders</li><li>Error Boundaries must be class components (no hook equivalent yet); wrap them in layout files</li><li>React Strict Mode double-invokes effects in development to catch missing cleanup; this does not happen in production</li><li>Use <code>React.lazy</code> + <code>Suspense</code> for code splitting at the route or component level</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',31)])])}const h=t(s,[["render",a]]);export{m as __pageData,h as default};
